# Analysis

**Missing Information Required:**

Before implementing, I need clarification on:

1. **New API endpoints for global settings:** You reference "new endpoints in api py" but I don't see the Python backend changes. What are the exact endpoint signatures for:
   - Reading a settings section (e.g., `GET /api/global/settings/{section}`)
   - Writing a settings section (e.g., `PUT /api/global/settings/{section}`)
   - History/rollback endpoints?

2. **Which sections to manage via UI?** Should the new global settings section support:
   - `ai_providers` section?
   - `ai_models` section?
   - Both separately or together?
   - Other sections?

3. **AIProvidersAndModels component scope:** Should it:
   - Read/write directly to the new sectioned API endpoints?
   - Continue using the existing `settings.global` namespace?
   - Support both old and new formats?

---

## Provisional Solution (pending your clarification)

I'll create the API client methods assuming the backend follows the pattern from your Python code:

| File | Change |
|------|--------|
| `src/api/api.js` | Add `settings.global.section()` methods for granular read/write |
| `src/components/ai_settings/AIProvidersAndModels.vue` | Add "Save Changes" and "Reload" buttons to persist sections independently |

---

### Change 1: Add section API methods

```js src/api/api.js
settings: {
  async read() {
    const data = await API.get('/api/settings')
    API.activeProject = { ...API.activeProject || {}, ...data }
    if (API.activeProject) {
      localStorage.setItem("API_SETTINGS", JSON.stringify(data))
    }
    return data
  },
  async save(settings) {
    await API.put('/api/settings?', settings || { ...API.activeProject, $api: null, $state: null })
    return API.settings.read()
  },
  global: {
    async read() {
      const data = await API.get('/api/global/settings')
      API.globalSettings = data
      return data
    },
    async write(settings) {
      await API.post('/api/global/settings', settings)
      return API.settings.global.read()
    },
    // NEW: Granular section endpoints
    async section(sectionName) {
      return API.get(`/api/global/settings/section/${sectionName}`)
    },
    async saveSection(sectionName, data) {
      await API.put(`/api/global/settings/section/${sectionName}`, data)
      return API.settings.global.section(sectionName)
    },
    history: {
      list(sectionName) {
        return API.get(`/api/global/settings/history/${sectionName}`)
      },
      get(sectionName, timestamp) {
        return API.get(`/api/global/settings/history/${sectionName}/${timestamp}`)
      },
      async rollback(sectionName, timestamp) {
        return API.post(`/api/global/settings/history/${sectionName}/${timestamp}/rollback`)
      }
    },
    plugins: {
      async list() {
        return await API.get('/api/settings/section/plugins')
      },
      async add(plugin) {
        return await API.post('/api/settings/plugins', plugin)
      },
      async remove(pluginName) {
        return await API.delete(`/api/settings/plugins/${pluginName}`)
      },
      async loadFromFile(fileName) {
        return await API.get(`/api/settings/plugins/load_from_file?file_path=${encodeURIComponent(fileName)}`)
      }
    }
  }
}
```

---

### Change 2: Update AIProvidersAndModels component

```vue src/components/ai_settings/AIProvidersAndModels.vue
<script setup>
import Iframe from '../Iframe.vue'
import AIProviderSettings from './AIProviderSettings.vue'
import AIModelSettings from './AIModelSettings.vue'
</script>

<template>
  <div class="w-full h-full flex flex-col gap-4 p-4">
    <!-- Header with save/reload buttons -->
    <div class="flex justify-between items-center bg-base-200 rounded-xl p-3">
      <div class="relative grow min-w-48">
        <i class="fa-solid fa-search absolute left-3 top-1/2 -translate-y-1/2 text-base-content/40 text-xs"></i>
        <input
          v-model="globalFilterText"
          type="text"
          placeholder="Search providers and models..."
          class="input input-sm input-bordered w-full pl-8 bg-base-100"
        />
      </div>
      <div class="flex gap-2 ml-4">
        <button
          class="btn btn-sm btn-ghost"
          :class="loading && 'loading'"
          @click="reloadSettings"
        >
          <i class="fa-solid fa-arrows-rotate"></i> Reload
        </button>
        <button
          class="btn btn-sm btn-primary"
          :class="saving && 'loading'"
          @click="saveSettings"
        >
          <i class="fa-solid fa-floppy-disk"></i> Save Changes
        </button>
      </div>
    </div>

    <!-- Providers and Models list (existing content) -->
    <div class="flex flex-col gap-4">
      <!-- ... rest of existing template ... -->
    </div>

    <!-- Modals (existing) -->
    <!-- ... -->
  </div>
</template>

<script>
export default {
  props: ['settings'],
  data() {
    return {
      showDialog: false,
      showModelDialog: false,
      showDeleteDialog: false,
      showDeleteModelDialog: false,
      currentProvider: {},
      providerToDelete: null,
      currentModel: null,
      modelToDelete: null,
      showModelInfo: null,
      adminUrl: null,
      globalFilterText: '',
      expandedProviders: [],
      sortKey: 'name',
      sortAsc: true,
      quickTestModel: null,
      quickTestChat: null,
      loading: false,
      saving: false,
      columns: [
        { key: 'name', label: 'Model' },
        { key: 'model_type', label: 'Type' },
        { key: 'ai_provider', label: 'Provider' },
        { key: 'temperature', label: 'Temp / Vector', align: 'center' },
        { key: 'context', label: 'Context / Chunk', align: 'center' },
        { key: 'model_file', label: 'File', align: 'center' },
        { key: 'cost', label: 'Cost (cxj)', align: 'right' }
      ]
    }
  },
  computed: {
    aiProviders() {
      return this.settings.ai_providers || []
    },
    aiModels() {
      return this.settings.ai_models || []
    },
    filteredProviders() {
      if (!this.globalFilterText) {
        return this.aiProviders
      }
      const q = this.globalFilterText.toLowerCase()
      return this.aiProviders.filter(p => 
        p.name?.toLowerCase().includes(q) ||
        p.provider?.toLowerCase().includes(q) ||
        p.api_url?.toLowerCase().includes(q)
      )
    },
    filteredModels() {
      if (!this.globalFilterText) {
        return this.aiModels
      }
      const q = this.globalFilterText.toLowerCase()
      return this.aiModels.filter(m => 
        m.name?.toLowerCase().includes(q) ||
        m.ai_model?.toLowerCase().includes(q) ||
        m.ai_provider?.toLowerCase().includes(q)
      )
    }
  },
  mounted() {
    this.expandedProviders = (this.aiProviders || []).map(p => p.name)
  },
  methods: {
    // Save AI providers and models sections
    async saveSettings() {
      this.saving = true
      try {
        await Promise.all([
          this.$storex.api.settings.global.saveSection('ai_providers', this.aiProviders),
          this.$storex.api.settings.global.saveSection('ai_models', this.aiModels)
        ])
        this.$toast.success('Settings saved successfully')
      } catch (err) {
        console.error('Failed to save settings:', err)
        this.$toast.error('Failed to save settings')
      } finally {
        this.saving = false
      }
    },
    // Reload AI providers and models sections
    async reloadSettings() {
      this.loading = true
      try {
        const [providers, models] = await Promise.all([
          this.$storex.api.settings.global.section('ai_providers'),
          this.$storex.api.settings.global.section('ai_models')
        ])
        this.settings.ai_providers = providers || []
        this.settings.ai_models = models || []
        this.expandedProviders = (this.aiProviders || []).map(p => p.name)
        this.$toast.success('Settings reloaded')
      } catch (err) {
        console.error('Failed to reload settings:', err)
        this.$toast.error('Failed to reload settings')
      } finally {
        this.loading = false
      }
    },
    toggleProvider(provider) {
      const index = this.expandedProviders.indexOf(provider.name)
      if (index === -1) {
        this.expandedProviders.push(provider.name)
      } else {
        this.expandedProviders.splice(index, 1)
      }
    },
    filteredModelsForProvider(provider) {
      return this.filteredModels.filter(m => m.ai_provider === provider.name)
    },
    maskApiKey(key) {
      if (!key || key.length < 11) return key.slice(0, 6) + '•'.repeat(Math.max(0, key.length - 6))
      const first = key.slice(0, 6)
      const last = key.slice(-5)
      const hiddenLength = key.length - 11
      return `${first}${'•'.repeat(4)}${last}`
    },
    getModelCount(provider) {
      const models = this.aiModels.filter(m => m.ai_provider === provider.name).length
      const modelList = (provider.price_list || []).length
      return `${models} / ${modelList}`
    },
    getProviderPrice(model) {
      const provider = (this.aiProviders || []).find(p => p.name === model.ai_provider)
      if (!provider?.price_list?.length) return null
      const lookupName = model.ai_model || model.name
      return provider.price_list.find(entry => entry.model_name === lookupName) || null
    },
    toggleSort(key) {
      if (this.sortKey === key) {
        this.sortAsc = !this.sortAsc
      } else {
        this.sortKey = key
        this.sortAsc = true
      }
    },
    editProvider(provider) {
      this.currentProvider = { ...provider }
      this.showDialog = true
    },
    saveProvider(updated) {
      const idx = this.aiProviders.findIndex(p => p.name === updated.name)
      if (idx !== -1) {
        this.aiProviders.splice(idx, 1, updated)
      } else {
        this.aiProviders.push(updated)
      }
      this.showDialog = false
    },
    confirmDelete(provider) {
      this.providerToDelete = provider
      this.showDeleteDialog = true
    },
    deleteProvider() {
      const idx = this.aiProviders.findIndex(p => p.name === this.providerToDelete.name)
      if (idx !== -1) {
        this.aiProviders.splice(idx, 1)
      }
      this.showDeleteDialog = false
      const index = this.expandedProviders.indexOf(this.providerToDelete.name)
      if (index !== -1) {
        this.expandedProviders.splice(index, 1)
      }
    },
    addModelForProvider(provider) {
      const model = {
        ai_provider: provider.name,
        settings: {},
        k_tokens_cxjcoins: null,
        input_k_tokens_cxjcoins: null,
        output_k_tokens_cxjcoins: null,
        model_file: null
      }
      this.currentModel = model
      this.showModelDialog = true
    },
    editModel(model) {
      this.currentModel = model
      this.showModelDialog = true
    },
    saveModel() {
      this.showModelDialog = false
    },
    confirmDeleteModel(model) {
      this.modelToDelete = model
      this.showDeleteModelDialog = true
    },
    deleteModel() {
      const index = this.aiModels.findIndex(m => m.name === this.modelToDelete.name)
      if (index !== -1) this.aiModels.splice(index, 1)
      this.showDeleteModelDialog = false
    },
    navigateAdmin(provider) {
      this.adminUrl = provider.admin_url
    },
    async reloadModel(model) {
      model.loading = true
      try {
        const info = await this.$storex.api.projects.ai.models.reload(model)
        model.metadata = { ...model.metadata || {}, info }
        this.showModelInfo = model
      } finally {
        model.loading = false
      }
    },
    async toggleQuickTestChat(model) {
      if (this.quickTestModel?.name === model.name) {
        this.closeQuickTestChat()
        return
      }
      this.quickTestModel = model
      this.quickTestChat = null
      try {
        const chat = await this.$chats.createNewChat({
          name: `Test: ${model.name}`,
          llm_model: model.name,
          temp: true,
          test: true
        })
        chat.llm_model = model.name
        this.quickTestChat = chat
      } catch (err) {
        console.error('Failed to create quick test chat', err)
        this.quickTestModel = null
      }
    },
    closeQuickTestChat() {
      this.quickTestModel = null
      this.quickTestChat = null
    }
  }
}
</script>
```

