      return new Promise((ok, ko) => {
        const ix = setInterval(async () => {
          if (--waitTime) {
            try {
              await API.init()
              clearInterval(ix)
              ok()
            } catch { }
          } else {
            clearInterval(ix)
            ko()
          }
        }, 5000)
      })
